/**
 * Before an edit (Claude Code PreToolUse, Cursor preToolUse): refuses edits to
 * generated files and tells the agent what to change instead.
 */
import { relative } from "node:path";
import { root } from "../lib/checks.ts";
import { editedFile, readInput, tellAgent } from "../lib/hook.ts";

const generated: readonly (readonly [RegExp, string])[] = [
  [/^dist\//, "dist/ is generated by `npm run build`: edit src/ or public/ instead."],
  [/^node_modules\//, "node_modules/ is installed by npm: never edit it."],
  [/^package-lock\.json$/, "package-lock.json is written by npm: run `npm install <package>` instead."],
];

const input = readInput();
const file = editedFile(input);
if (file === undefined) process.exit(0);

const path = relative(root, file);
for (const [pattern, reason] of generated) {
  if (pattern.test(path)) {
    tellAgent(input, reason, (message) => ({ permission: "deny", agent_message: message, user_message: message }));
  }
}
